def upgrade() -> None:
    """Upgrade schema."""
    import re
    # ### commands auto generated by Alembic - please adjust! ###
    op.create_table('idempotency_records',
    sa.Column('key', sa.String(length=128), nullable=False),
    sa.Column('endpoint', sa.String(length=128), nullable=False),
    sa.Column('response_code', sa.Integer(), nullable=False),
    sa.Column('response_body', sa.JSON(), nullable=False),
    sa.Column('created_at', sa.DateTime(timezone=True), nullable=False),
    sa.PrimaryKeyConstraint('key', 'endpoint')
    )
    op.create_table('number_sequences',
    sa.Column('name', sa.String(length=50), nullable=False),
    sa.Column('year', sa.Integer(), nullable=False),
    sa.Column('last_value', sa.Integer(), nullable=False),
    sa.PrimaryKeyConstraint('name', 'year')
    )

    # Seed current sequences from max existing numbers
    conn = op.get_bind()

    # ADM
    max_adm_val = 0
    max_adm_year = 2026
    adm_rows = conn.execute(sa.text("SELECT admission_number FROM admissions")).fetchall()
    for row in adm_rows:
        num = row[0]
        m = re.match(r"^ADM-(\d{4})-(\d+)$", num or "")
        if m:
            yr = int(m.group(1))
            val = int(m.group(2))
            if yr == max_adm_year and val > max_adm_val:
                max_adm_val = val

    # PAY
    max_pay_val = 0
    max_pay_year = 2026
    pay_rows = conn.execute(sa.text("SELECT payment_number FROM payments")).fetchall()
    for row in pay_rows:
        num = row[0]
        m = re.match(r"^PAY(\d{4})(\d+)$", num or "")
        if m:
            yr = int(m.group(1))
            val = int(m.group(2))
            if yr == max_pay_year and val > max_pay_val:
                max_pay_val = val

    # REF
    max_ref_val = 0
    max_ref_year = 2026
    ref_rows = conn.execute(sa.text("SELECT refund_number FROM refunds")).fetchall()
    for row in ref_rows:
        num = row[0]
        m = re.match(r"^REF(\d{4})(\d+)$", num or "")
        if m:
            yr = int(m.group(1))
            val = int(m.group(2))
            if yr == max_ref_year and val > max_ref_val:
                max_ref_val = val

    conn.execute(sa.text("""
        INSERT INTO number_sequences (name, year, last_value)
        VALUES
            ('ADM', :adm_year, :adm_val),
            ('PAY', :pay_year, :pay_val),
            ('REF', :ref_year, :ref_val)
        ON CONFLICT (name, year) DO UPDATE SET last_value = EXCLUDED.last_value;
    """), {
        "adm_year": max_adm_year, "adm_val": max_adm_val,
        "pay_year": max_pay_year, "pay_val": max_pay_val,
        "ref_year": max_ref_year, "ref_val": max_ref_val
    })
    # ### end Alembic commands ###


